var HELP_DETAILS={"home":{"img":"data:image/jpeg;base64,","steps":["下滑阅读「作者的话」与十二件非遗轮播。","点「步入展厅」进入展品总览，或「先问一个问题」直接对话。","右上角「使用说明」随时回看；「沉浸演绎」在导航栏最右侧。"]},"hall":{"img":"data:image/jpeg;base64,","steps":["顶部按门类筛选：戏曲 / 曲艺 / 技艺 / 美术 / 体育 / 民俗 / 全部。","点卡片右上角「藏」章一键收藏，收藏后变朱砂色。","点卡片进入详情页：可收藏、点赞，已收藏在「已收藏」筛选中可清空。"]},"map":{"img":"data:image/jpeg;base64,","steps":["鼠标悬停地市红点：其余红点与名称隐去，只亮当前一项。","点击城市板块：进入该城市介绍。","左下三键：放大 / 缩小 / 复位，支持滚轮缩放。"]},"region":{"img":"data:image/jpeg;base64,","steps":["中原十八城卡片，每城配标志建筑图与城市别称。","带「非遗」角标的城市藏有招牌项目，点击卡片进详情。"]},"graph":{"img":"data:image/jpeg;base64,","steps":["拖拽平移图谱，鼠标滚轮以中心为轴缩放。","悬停任意节点：其余节点与名称隐去，突出该点关联脉络。","点击项目节点进入该非遗详情。"]},"treasury":{"img":"data:image/jpeg;base64,","steps":["数字讲解员「文昭」真人真声逐件导览，口唇随讲解音频自然开合，声波实时起伏。","字幕与图文考据点随播放进度分段点亮；点击段落标签或考据点即可跳段重听。","进度条可点击、可拖动，支持静音；上一件 / 下一件切换五件珍品，讲解自动接续。","右栏可调阅实物影像、六步工艺流程图文演示与工艺知识卡。"]},"ask":{"img":"data:image/jpeg;base64,","steps":["输入任意非遗问题，或点击下方快捷提问。","内置知识库离线即时作答，回答流式逐字显现。","接入豆包 / 千问 API（app.js REMOTE_API）后自动升级为真·大模型回答。"]},"create":{"img":"data:image/jpeg;base64,","steps":["选一件展品，再选一种风格：水墨 / 朱砂 / 描金 / 拓印。","点「生成」即时合成非遗海报，可下载 PNG。","「复制分享文案」一键复制配套文案。"]},"evolution":{"img":"data:image/jpeg;base64,","steps":["十二轮迭代时间轴，滚动阅读每一步演进。","每轮含关键 Prompt、AI 协作要点、引导修复记录。","与仓库 Git 提交日志、AI 对话快照一一对应，评委可一键复现。"]},"immerse":{"img":"data:image/jpeg;base64,","steps":["左右箭头或键盘 ← / → 切换展品。","进入页面自动播放，鼠标悬停暂停，移开继续。","视频为 B 站权威专题片，可点击跳转原片。"]}};
